import java.util.*;

public class Main {
    class CustomStack {
        int maxSize;
        List<Integer> stack = new ArrayList<>();

        CustomStack(int maxSize) { this.maxSize = maxSize; }

        void push(int x) {
            if (stack.size() < maxSize) stack.add(x);
        }

        int pop() {
            if (stack.isEmpty()) return -1;
            return stack.remove(stack.size() - 1);
        }

        void increment(int k, int val) {
            for (int i = 0; i < Math.min(k, stack.size()); i++) {                    // walk the bottom min(k, size) elements one at a time
                stack.set(i, stack.get(i) + val);
            }
        }
    }

    public static void main(String[] args) {
        CustomStack cs = new CustomStack(3);
        cs.push(1);
        cs.push(2);
        System.out.println(cs.pop());
        cs.push(2);
        cs.push(3);
        cs.push(4);
        cs.increment(5, 100);
        cs.increment(2, 100);
        System.out.println(cs.pop());
        System.out.println(cs.pop());
        System.out.println(cs.pop());
        System.out.println(cs.pop());
    }
}

