#include <bits/stdc++.h>
using namespace std;

class CustomStack {
public:
    int maxSize;
    vector<int> stack;

    CustomStack(int maxSize) : maxSize(maxSize) {}

    void push(int x) {
        if ((int)stack.size() < maxSize) stack.push_back(x);
    }

    int pop() {
        if (stack.empty()) return -1;
        int top = stack.back();
        stack.pop_back();
        return top;
    }

    void increment(int k, int val) {
        for (int i = 0; i < min(k, (int)stack.size()); i++) {                       // walk the bottom min(k, size) elements one at a time
            stack[i] += val;
        }
    }
};

int main() {
    CustomStack cs(3);
    cs.push(1);
