import java.util.*;

public class Main {
    class CustomStack {
        int maxSize;
        int[] stack;
        int[] increments;                                                             // increments[i] = a PENDING increment for the element at position i
        int size = 0;

        CustomStack(int maxSize) {
            this.maxSize = maxSize;
            stack = new int[maxSize];
            increments = new int[maxSize];
        }

        void push(int x) {
            if (size < maxSize) stack[size++] = x;
        }

        int pop() {
            if (size == 0) return -1;
            size--;
            int val = stack[size] + increments[size];                                    // apply this element's own pending increment, right when it's popped
            if (size > 0) increments[size - 1] += increments[size];                         // push the pending increment DOWN to the new top, so it isn't lost
            increments[size] = 0;
            return val;
        }

        void increment(int k, int val) {
            if (size > 0) {
                int idx = Math.min(k, size) - 1;                                            // only record the increment at ONE position: the top of the affected range
                increments[idx] += val;
            }
        }
    }

    public static void main(String[] args) {
        CustomStack cs = new CustomStack(3);
        cs.push(1);
        cs.push(2);
        System.out.println(cs.pop());
        cs.push(2);
        cs.push(3);
        cs.push(4);
        cs.increment(5, 100);
        cs.increment(2, 100);
        System.out.println(cs.pop());
        System.out.println(cs.pop());
        System.out.println(cs.pop());
        System.out.println(cs.pop());
    }
}

